occ={(0,1),(0,2),(0,4),(0,5)} | {(1,c) for c in range(6)} | {(2,1),(2,2),(2,4)} | {(3,2),(3,3),(3,4)}
# tile motifs O and L triomino any rotation
pieces=[]
for typ, cells in [('O',[(0,0),(0,1),(1,0),(1,1)]), ('L',[(0,0),(0,1),(1,1)]),('L',[(0,0),(1,0),(1,1)]),('L',[(0,1),(1,0),(1,1)]),('L',[(0,0),(0,1),(1,0)])]:
    pass
# unique placements fully in occ
shapes={'O':{(0,0),(0,1),(1,0),(1,1)}, 'L_tl':{(0,1),(1,0),(1,1)}, 'L_bl':{(0,0),(0,1),(1,1)},'L_tr':{(0,0),(1,0),(1,1)}, 'L_br':{(0,0),(0,1),(1,0)}}
placements=[]
for name,sh in shapes.items():
  maxr=max(r for r,c in sh); maxc=max(c for r,c in sh)
  for r in range(4-maxr):
    for c in range(6-maxc):
      p={(r+rr,c+cc) for rr,cc in sh}
      if p<=occ: placements.append((name,p))
bycell={x:[] for x in occ}
for i,(n,p) in enumerate(placements):
  for x in p: bycell[x].append(i)
sol=[]
def rec(rem,chosen):
 if not rem:
  sol.append(chosen);return
 x=min(rem,key=lambda x:sum(placements[i][1]<=rem for i in bycell[x]))
 for i in bycell[x]:
  n,p=placements[i]
  if p<=rem: rec(rem-p,chosen+[placements[i]])
rec(occ,[])
len(sol), [[(n,sorted(p)) for n,p in s] for s in sol[:5]]
